@pytest.mark.parametrize(
    'i,fibre_cells,expected',
    material
)
def test_link_map(i, fibre_cells, expected):
    """
    Regression test from visually inspected outputs.
    """
    env, _, _ = env_generator(seed=44)
    stations_links = build_stations_and_links_payload(env)
    print(stations_links)

    link = stations_links["links"][i]
    actual = extract_link_map(stations_links, link, env, fibre_cells)
    assert list(actual.keys()) == list(expected.keys()) + ["levels"]
    for k in actual.keys():
        if k == 'grid':
            assert np.array_equal(actual[k], expected[k])
        # TODO re-generate after fixing levels
        elif k != "levels":
            assert actual[k] == expected[k]


def _gen_material():
    """Re-generate test assertions after visual inspection."""
    env, _, _ = env_generator(seed=44)
    stations_links = build_stations_and_links_payload(env)
    print(stations_links)

    material = []

    for i, current_link in enumerate(stations_links["links"]):
        fibre = current_link["fibres"][0]
        print("fibre")
        print(fibre)
        fibre_cells = fibre["cells"]

        link_map = extract_link_map(stations_links, current_link, env, fibre_cells)
        print(link_map)

        material.append((i, fibre_cells, link_map))
    print(f"material={str(material).replace("array(", "np.array(")}")
